  ],
  "contradictory_card_ids": ["C78","C83"],
  "prediction_basis_card_ids": [
    "C22","C23","C25","C14","C15","C17","C18","C24",
    "C01","C13","C16","C20","C04","C07","C08","C10",
    "C81","C79","C89"
  ],
  "claims": [
    {
      "claim": "Direct absolute/relative oral bioavailability measurements for structurally related beta-blockers all exceed the 20% threshold: pamatolol 64.9–103.5%, practolol 90–100%, pindolol 53–79.5%, diacetolol 30–43%, bufuralol 52–83%, and CP-331,684 27%.",
      "card_ids": ["C22","C23","C25","C14","C15","C17","C18","C24","C01","C13","C16","C20","C04","C07","C08","C10"]
    },
    {
      "claim": "L4 absorption evidence shows no solubility or permeability liability for the beta-blocker class: atenolol >1 mg/mL, acebutolol 4.08 mg/mL, propranolol high Caco-2 permeability ~3.4–3.7×10^-5 cm/s, and the closest urea-containing analog has water solubility 1.0 mg/mL.",
      "card_ids": ["C60","C55","C66","C62","C63","C58"]
    },
    {
      "claim": "L6 hepatic-clearance evidence indicates that urea/amide-containing para-substituted aryloxypropanolamines have low hepatic extraction (practolol low extraction; atenolol microsomal CLint 1.08 ml·min−1·g−1 liver), and the tert-butylamino motif is associated with CYP2D6-dominant metabolism (timolol >90% CYP2D6), which rifampin does not induce.",
      "card_ids": ["C81","C79","C89"]
    },
    {
      "claim": "L5 C78 shows celiprolol, a structurally similar aryloxypropanolamine urea, is subject to intestinal P-gp efflux; rifampin as a P-gp inducer could reduce absorption, but this does not quantify F or establish F<20%.",
      "card_ids": ["C78"]
    },
    {
      "claim": "L6 also includes CYP3A4-mediated metabolism for bisoprolol and metoprolol, but neither record provides a threshold-relevant low-F outcome for the query, and bisoprolol has high oral bioavailability despite CYP3A4 metabolism.",
      "card_ids": ["C83","C84"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C81","C79","C89"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query under rifampin or at baseline.",
    "No rifampin co-treatment PK data in any supplied record.",
    "No query-specific P-gp efflux, CYP3A4, or CYP2D6 metabolism measurement; C78 is celiprolol and L6 records are other beta-blockers.",
    "Baseline F of the query is unknown; transfer from beta-blocker analogs is indirect.",
    "L6 records do not provide numeric F or threshold-relevant low outcome."
  ],
  "decision_summary": "Predicted high because all transferable direct F records for structurally related beta-blockers exceed 20%, L4 absorption evidence supports adequate solubility/permeability, and L6 hepatic-clearance evidence shows low extraction for urea/amide beta-blockers and CYP2D6-dominant metabolism for the tert-butylamino motif, which rifampin does not induce. L5 P-gp efflux (C78) and L6 CYP3A4 records (C83/C84) raise mechanistic concerns under rifampin but do not affirmatively establish F<20%, so the high prediction is strengthened with moderate confidence."
}

